mapper.select:
SELECT /*selectSellerMpIvMkImScheduleRegList*/ ZZZ. * FROM (SELECT A. * , DECODE(MK_DATE||ADMIN_CHECK||AGENT_CHECK, '', '신규', MK_DATE||'checkedchecked', '완료', '진행')RECV_FLAG_NAME , DECODE(MK_DATE||ADMIN_CHECK||AGENT_CHECK, '', 'BG', MK_DATE||'checkedchecked', 'ED', 'IG')RECV_FLAG , TEXT1 MK_TYPE_NAME , MK.MK_DATE , MK.MK_SEQ , ADMIN_REMARK , AGENT_REMARK , ADMIN_IMAGE_KEY , AGENT_IMAGE_KEY , ADMIN_CHECK , AGENT_CHECK , (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'M132' AND CODE = A.ITEM_MAKE_TYPE ) ITEM_MAKE_TYPE_NAME FROM (SELECT DT.BUYER , (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = DT.BUYER ) BUYER_NAME , DT.PO_NO , DT.PO_SEQ , DT.REF_PR_NO , DT.BUYER_ITEM_NO , DT.ITEM_AMT , DT.DESCRIPTION , DT.SPECIFICATION , DT.ITEM_MAKE_TYPE , CD.CODE MK_TYPE , DT.RD_DATE , DT.DS_DATE , HD.PO_CREATE_DATE , CD.CODE , CD.TEXT1 , dt.LEGACY_PO_NO FROM ICOMPODT DT , ICOMPOHD HD , ICOMCOD1 CD WHERE 1 = 1 AND HD.BUYER = DT.BUYER AND HD.PO_NO = DT.PO_NO AND DT.ITEM_MAKE_TYPE IN ('MK', 'IM') AND DT.DS_DATE IS NOT NULL AND NOT EXISTS (SELECT 1 FROM ICOMIVDT WHERE BUYER = DT.BUYER AND PO_NO = DT.PO_NO AND PO_SEQ = DT.PO_SEQ AND STATUS IN ('C', 'R') ) AND DT.STATUS IN ('C', 'R') AND HD.AGENT = #{st_com_code } AND CD.TYPE = 'M133' AND CD.TEXT5 = DT.ITEM_MAKE_TYPE ) A , ICOMPOMK MK WHERE A.BUYER = MK.BUYER(+) AND A.PO_NO = MK.PO_NO(+) AND A.PO_SEQ = MK.PO_SEQ(+) AND A.CODE = MK.MK_TYPE(+)
AND a.BUYER = #{st_buyer_code}
AND (a.PO_NO LIKE UPPER(#{st_po_no}||'%') OR a.LEGACY_PO_NO LIKE UPPER(#{st_po_no}||'%'))
AND a.DESCRIPTION LIKE '%'||#{st_description}||'%'
AND a.BUYER_ITEM_NO LIKE #{st_buyer_item_no}||'%'
AND a.PO_CREATE_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND a.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND a.RD_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND MK.MK_DATE BETWEEN #{st_from_date} AND #{st_to_date}
AND a.ITEM_MAKE_TYPE = #{st_item_make_type}
) ZZZ WHERE 1=1
and RECV_FLAG = #{st_recv_flag }
ORDER BY BUYER, PO_NO, PO_SEQ, MK_SEQ

mapper.update:

MERGE INTO ICOMPOMK /* saveMkImScheduleReg */
USING DUAL
ON (BUYER = #{st_buyer }
 AND PO_NO = #{st_po_no }
 AND PO_SEQ = #{st_po_seq }
 AND MK_SEQ = #{st_mk_seq }
)
WHEN MATCHED THEN 
  UPDATE 
	 SET AGENT_REMARK = #{st_agent_remark}
	   , AGENT_IMAGE_KEY = #{st_agent_image_key}
	   , AGENT_CHECK = LOWER(#{st_agent_check})
	   , ADD_DATE = TO_CHAR(SYSDATE, 'yyyymmdd')
	   , ADD_TIME = TO_CHAR(SYSDATE, 'hh24miss')
	   , ADD_USER_ID = #{st_user_id }
	   , STATUS = 'R'
	   , COMPLETE_MARK = CASE WHEN ADMIN_CHECK = 'checked' AND AGENT_CHECK = 'checked' THEN 'Y' ELSE 'N' END
WHEN NOT MATCHED THEN
		insert
		(
		   BUYER
		 , PO_NO
		 , PO_SEQ
		 , MK_SEQ
		 , STATUS
		 , ADD_DATE
		 , ADD_TIME
		 , AGENT
		 , BUYER_ITEM_NO
		 , ITEM_MAKE_TYPE
		 , MK_TYPE
		 , MK_DATE
		 , ADD_USER_ID
		 , AGENT_REMARK
		 , AGENT_IMAGE_KEY
		 , AGENT_CHECK
	   ) values (
		   #{st_buyer }
		 , #{st_po_no }
		 , #{st_po_seq }
		 , #{st_mk_seq }
		 , 'C'
		 , TO_CHAR(SYSDATE, 'yyyymmdd')
		 , TO_CHAR(SYSDATE, 'hh24miss')
		 , #{st_com_code }
		 , #{st_buyer_item_no }
		 , #{st_item_make_type }
		 , #{st_mk_type }
		 , #{st_mk_date }
		 , #{st_user_id }
		 , #{st_agent_remark }
		 , #{st_agent_image_key }
		 , LOWER(#{st_agent_check })
		)


INSERT INTO ICOMPOMK /*saveMkImScheduleReg*/
	   (
		   BUYER
		 , PO_NO
		 , PO_SEQ
		 , MK_SEQ
		 , STATUS
		 , ADD_DATE
		 , ADD_TIME
		 , AGENT
		 , BUYER_ITEM_NO
		 , ITEM_MAKE_TYPE
		 , MK_TYPE
		 , MK_DATE
		 , ADD_USER_ID
		 , AGENT_REMARK
		 , AGENT_IMAGE_KEY
	   ) 
	   VALUES 
	   (
		   #{st_buyer }
		 , #{st_po_no }
		 , #{st_po_seq }
		 , #{st_mk_seq }
		 , 'C'
		 , TO_CHAR(SYSDATE, 'yyyymmdd')
		 , TO_CHAR(SYSDATE, 'hh24miss')
		 , #{st_com_code }
		 , #{st_buyer_item_no }
		 , #{st_item_make_type }
		 , #{st_mk_type }
		 , #{st_mk_date }
		 , #{st_user_id }
		 , #{st_agent_remark }
		 , #{st_agent_image_key }
	   )


UPDATE ICOMPOMK /*saveMkImScheduleUpdate*/
   SET ADMIN_REMARK = #{st_admin_remark } 
	 , AGENT_IMAGE_KEY = #{st_agent_image_key }
	 , CHANGE_DATE = TO_CHAR(SYSDATE, 'yyyymmdd')
	 , CHANGE_TIME = TO_CHAR(SYSDATE, 'hh24miss')
	 , STATUS = 'R'
 WHERE BUYER = #{st_buyer }
   AND PO_NO = #{st_po_no }
   AND PO_SEQ = #{st_po_seq }
   AND MK_SEQ = #{st_mk_seq }
